import Card from "@/components/ui/card";
import Button from "@/components/ui/button";
import { MesaAsignada } from "@/types/mesero";

interface MesaAsignadaCardProps {
  mesa: MesaAsignada;
  onAceptar: (id: string) => void;
  onTransferir: (id: string) => void;
  onVerComandas: (id: string) => void;
}

export default function MesaAsignadaCard({
  mesa,
  onAceptar,
  onTransferir,
  onVerComandas,
}: MesaAsignadaCardProps) {
  return (
    <Card className="p-5">
      <div className="flex items-center justify-between">
        {/* Info izquierda */}
        <div className="space-y-1">
          <p className="text-lg font-bold text-gray-800">
            Mesa {mesa.numero}
          </p>
          <p className="text-sm text-gray-500">👤 {mesa.personas} personas</p>
          <p className="text-sm text-gray-500">📍 {mesa.ubicacion}</p>
        </div>

        {/* Botones derecha */}
        <div className="flex gap-2">
          {!mesa.aceptada ? (
            <>
              <Button variant="primary" onClick={() => onAceptar(mesa.id)}>
                Aceptar
              </Button>
              <Button variant="secondary" onClick={() => onTransferir(mesa.id)}>
                Transferir
              </Button>
            </>
          ) : (
            <Button variant="primary" onClick={() => onVerComandas(mesa.id)}>
              Ver Comandas
            </Button>
          )}
        </div>
      </div>
    </Card>
  );
}
