"use client";

import { useState } from "react";
import { useRouter } from "next/navigation";
import { FiltroMesa, MesaAsignada } from "@/types/mesero";
import HeaderMesero from "../components/header-mesero";
import FiltroMesas from "./components/filtro-mesas";
import ListaMesas from "./components/lista-mesas";

const mesasMock: MesaAsignada[] = [
  { id: "1", numero: 1, personas: 4, ubicacion: "Terraza", aceptada: false },
  { id: "2", numero: 3, personas: 2, ubicacion: "Salón", aceptada: false },
  { id: "3", numero: 5, personas: 6, ubicacion: "Terraza", aceptada: true },
  { id: "4", numero: 7, personas: 3, ubicacion: "Salón", aceptada: true },
  { id: "5", numero: 9, personas: 5, ubicacion: "Jardín", aceptada: false },
  { id: "6", numero: 12, personas: 2, ubicacion: "Barra", aceptada: true },
];

export default function MesasMeseroPage() {
  const router = useRouter();
  const [filtro, setFiltro] = useState<FiltroMesa>("asignadas");
  const [mesas, setMesas] = useState<MesaAsignada[]>(mesasMock);

  const mesasFiltradas = mesas.filter((m) =>
    filtro === "asignadas" ? !m.aceptada : m.aceptada
  );

  const handleAceptar = (id: string) => {
    const mesa = mesas.find((m) => m.id === id);
    setMesas((prev) =>
      prev.map((m) => (m.id === id ? { ...m, aceptada: true } : m))
    );
    if (mesa) {
      router.push(`/mesero/mesas/${mesa.numero}/menu`);
    }
  };

  const handleTransferir = (id: string) => {
    alert(`Transferir mesa ${id}`);
  };

  const handleVerComandas = (id: string) => {
    const mesa = mesas.find((m) => m.id === id);
    if (mesa) {
      router.push(`/mesero/mesas/${mesa.numero}/comandas`);
    }
  };

  return (
    <div className="min-h-screen bg-gray-50">
      <HeaderMesero seccion="Asignaciones" />

      <main className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 py-6 space-y-6">
        <FiltroMesas filtro={filtro} onChangeFiltro={setFiltro} />
        <ListaMesas
          mesas={mesasFiltradas}
          filtro={filtro}
          onAceptar={handleAceptar}
          onTransferir={handleTransferir}
          onVerComandas={handleVerComandas}
        />
      </main>
    </div>
  );
}

