import { MesaAsignada, FiltroMesa } from "@/types/mesero";
import MesaAsignadaCard from "./mesa-asignada-card";

interface ListaMesasProps {
  mesas: MesaAsignada[];
  filtro: FiltroMesa;
  onAceptar: (id: string) => void;
  onTransferir: (id: string) => void;
  onVerComandas: (id: string) => void;
}

export default function ListaMesas({
  mesas,
  filtro,
  onAceptar,
  onTransferir,
  onVerComandas,
}: ListaMesasProps) {
  return (
    <div className="grid gap-4">
      {mesas.length === 0 && (
        <p className="text-gray-400 text-center py-10">
          No hay mesas {filtro} por el momento.
        </p>
      )}

      {mesas.map((mesa) => (
        <MesaAsignadaCard
          key={mesa.id}
          mesa={mesa}
          onAceptar={onAceptar}
          onTransferir={onTransferir}
          onVerComandas={onVerComandas}
        />
      ))}
    </div>
  );
}
