import Button from "@/components/ui/button";
import { FiltroMesa } from "@/types/mesero";

interface FiltroMesasProps {
  filtro: FiltroMesa;
  onChangeFiltro: (filtro: FiltroMesa) => void;
}

export default function FiltroMesas({ filtro, onChangeFiltro }: FiltroMesasProps) {
  return (
    <div className="flex gap-3">
      <Button
        variant={filtro === "asignadas" ? "primary" : "secondary"}
        onClick={() => onChangeFiltro("asignadas")}
      >
        Mesas Asignadas
      </Button>
      <Button
        variant={filtro === "aceptadas" ? "primary" : "secondary"}
        onClick={() => onChangeFiltro("aceptadas")}
      >
        Mesas Aceptadas
      </Button>
    </div>
  );
}
